#!/usr/bin/env bash
# 只更新 /var/www/xinmo-site 的静态文件，不影响服务配置。
set -euo pipefail
echo "== 解包站点 =="
mkdir -p /tmp/xm-site-upd
echo '' | base64 -d > /tmp/xm-site-upd/site.tar.gz
rm -rf /tmp/xm-site-upd/site
mkdir -p /tmp/xm-site-upd/site
tar -xzf /tmp/xm-site-upd/site.tar.gz -C /tmp/xm-site-upd/site
echo "== 覆盖静态站（保留可能的上传文件）=="
sudo cp -r /tmp/xm-site-upd/site/. /var/www/xinmo-site/
sudo chown -R www-data:www-data /var/www/xinmo-site 2>/dev/null || true
echo "== 校验关键文件 =="
ls -l /var/www/xinmo-site/assets/js/dynamic.js
ls -l /var/www/xinmo-site/profile.html /var/www/xinmo-site/search.html
grep -c 'data-xm-comments' /var/www/xinmo-site/tools/slotrunner/index.html || true
echo "== DONE =="
